        ...(event.kind === "step" ? { step: event.step } : {}),
        ...(event.kind === "waiting" ? { waiting: event.waiting ?? "none" } : {}),
        ...(event.kind === "published" ? { prNumber: event.prNumber } : {}),
        ...(event.kind === "finished" ? { state: event.state, ...(event.failure ? { failure: event.failure } : {}) } : {}),
